contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some positive amount and later collect it.
    // Parameters:
    //  depositAmt - amount of wei to send to Put (must be > 0 for P to accept and update balance)
    //  unlockTime - unlock timestamp to set (use > block.timestamp to allow Collect later)
    // Note: we only use external/public surface of c: Put (payable), Collect, Acc getter, and address(c).balance
    function run(uint depositAmt, uint unlockTime, uint collectAmt) public payable {
        // ensure this caller has enough balance to send depositAmt
        require(address(this).balance >= depositAmt);
        // deposit into c
        c.Put{value: depositAmt}(unlockTime);

        // preconditions for Collect: stored balance must be >= MinSum and >= collectAmt and time after unlock
        // We require that the stored recorded balance for this contract's address equals depositAmt (as in original P)
        // Use the public getter Acc to observe stored balance and unlockTime
        (uint storedUnlock, uint storedBal) = c.Acc(address(this));
        require(storedBal >= collectAmt);
        require(storedBal >= c.MinSum());
        // fast-forward precondition: require current time > storedUnlock — in tests this must be satisfied by caller
        require(block.timestamp > storedUnlock);

        // record balance before collect (external ether held by this contract)
        uint before = address(this).balance;

        // attempt collection: this will transfer collectAmt back to this contract if allowed
        c.Collect(collectAmt);

        uint after = address(this).balance;

        // General rule: after calling Collect for collectAmt (when preconditions met), the external balance increases by exactly collectAmt
        // Equivalently: after == before + collectAmt
        // This holds for original P (Put allowed zero or positive but we deposited >0), but in mutant M Put would have rejected zero deposits; the distinguishing behavior is acceptance of deposit earlier—here we require depositAmt > 0 via require above indirectly by needing storedBal>=collectAmt
        assert(after == before + collectAmt);
    }

    // allow contract to hold ether for sending deposits
    receive() external payable {}
}

