import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 deposit, uint256 _unlockTime) public {
        // admissible domain: non-zero deposit keeps things meaningful; keep wide bounds
        deposit = deposit == 0 ? 1 wei : deposit;
        // fund the actor so they can send ether
        vm.deal(actor, deposit);
        // ensure time is some arbitrary fuzzed timestamp (allow wide range)
        // warp to a known baseline to make behaviour deterministic relative to block.timestamp
        // use _unlockTime directly as input to Put
        vm.prank(actor);
        bool ok;
        // perform the payable call from actor to c.Put(_unlockTime)
        try c.Put{value: deposit}(_unlockTime) {
            ok = true;
        } catch {
            ok = false;
