pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        // deploy reference C pointing its LogFile to this test (address(this)) as required by constructor
        c = new C(address(this));
        // deploy an attacker helper that will re-enter via the AddMessage call point (log contract call site)
        attacker = new Attacker(address(c));
    }

    // Fuzzed parameters: amount to send and an unlockTime candidate
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // keep amount in reasonable bounds (not too large to overflow tests) but wide
        vm.assume(amount <= type(uint128).max);
        vm.assume(unlockTime <= type(uint256).max);

        // fund attacker EOA so it can send ETH when acting
        vm.deal(address(attacker), amount + 1 ether);

        // Before action, record previous saved balance for attacker address
        uint256 before = c.Acc(address(attacker));

        // Arrange: set the C contract's LogFile to the attacker so that when C calls LogFile.AddMessage
        // it will call into the attacker which re-enters back into C during Put execution.
        // We must call C's constructor already set LogFile to address(this), but C does not expose a setter.
        // However, the contract C will call LogFile.AddMessage(msg.sender,msg.value,"Put");
        // The LogFile is the contract deployed at address passed in constructor. We deployed C with address(this),
        // but we want the AddMessage call to go to attacker. To achieve that, we deploy a forwarder (Attacker)
        // and have it call C.Put while spoofing msg.sender to attacker so Acc mapping key matches.

        // We'll have the attacker perform the payable Put call and during the AddMessage callback the attacker will reenter.
        // Prank as attacker EOA so that msg.sender inside C is attacker address.
        vm.startPrank(address(attacker));
        // Let attacker call Put on c with provided unlockTime and amount
        // Attacker contract's fallback/addMessage will attempt reentrancy to exploit the ordering difference
        // Use low-level call to c.Put with value
        (bool ok, ) = address(attacker).call{value: 0}(abi.encodeWithSignature("doPut(address,uint256,uint256)", address(c), unlockTime, amount));
        // stop prank
        vm.stopPrank();

        // After operation, read stored balance
        uint256 after = c.Acc(address(attacker));

        // The universal invariant for the correct contract is: after == before + amount
        // This should hold for the reference implementation for all inputs; the mutant that sets unlockTime before
        // updating balance can be reentrancy-exploited during LogFile.AddMessage to break this equality for some inputs.
        assertTrue(after == before + amount);
    }
}

// Helper attacker contract that will be used as the caller and also will be the callee for LogFile.AddMessage
// It performs the Put call to C and when C calls back into this contract (as LogFile.AddMessage), the attacker
// re-enters C.Put to disturb ordering if the mutant is present.
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
    }

    // Called by test to start the sequence. We call C.Put as this contract so msg.sender is this contract.
    function doPut(address caddr, uint256 unlockTime, uint256 amount) public payable {
        // send amount with the call
        (bool s, ) = caddr.call{value: amount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        require(s, "Put failed");
    }

    // This function matches Log.AddMessage signature (address,uint,string) but solidity will route calls
    // by selector; to be safe provide a fallback that will be invoked by low-level call from C to LogFile.AddMessage
    // during Put. Inside this callback we attempt to re-enter C by calling Collect with 0 to cause reads/writes.
    fallback() external payable {
        // only reenter once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt a reentrant call to target. We call a view or non-state-changing function: but to affect storage ordering
            // we trigger another Put of 0 value to reenter and observe ordering differences in mutant.
            // Call Put with zero value and zero unlockTime
            (bool s, ) = target.call{value: 0}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
            s; // silence
        }
    }
}

