    // external LogFile.AddMessage call and break this invariant. We fuzz msgValue and _unlockTime.
    function testFuzz_property(uint256 msgValue, uint256 unlockTime) public {
        // keep msgValue within reasonable bounds and non-zero to exercise behavior
        msgValue = bound(msgValue, 0, 5 ether);

        // deploy an attacker that will revert inside Log.AddMessage by being the Log contract
        // The reference contract writes to LogFile.AddMessage(msg.sender,msg.value,"Put")
        // If we deploy an attacker Log that, during AddMessage, calls back into c.Put to attempt reentrancy,
        // the ordering difference can change final stored balance in mutant but not in reference.
        attacker = new Attacker(address(c));

        // Replace LogFile with attacker by constructing new C with address(this) already done in setUp;
        // But C's constructor took the log address; setUp already passed address(this). We cannot redeploy c
        // (must use new C(address(this)) per instructions). Instead, we will simulate the external Log behavior
        // by making the attacker the msg.sender in Put (since LogFile.AddMessage is called on LogFile, which
        // is fixed). To achieve an external reentrancy during Put we will make the caller be the attacker and
        // have the attacker's fallback call back into c.Put. The difference manifests when the external call
        // from C to LogFile.AddMessage triggers code at LogFile; so we need the LogFile to be a contract with code.
        // But c was constructed with address(this) as LogFile. So we must make this contract behave as LogFile and
        // during AddMessage perform reentrancy when called by c. We'll use vm.prank to call c.Put from attacker address
        // and have this contract's AddMessage detect when it's invoked by c and then cause reentrancy by calling back.

        // Ensure this contract has enough balance to let c send/receive if needed
        vm.deal(address(this), 10 ether);

        // Record initial balance stored for the attacker address in c
        address caller = address(attacker);
        // Give attacker some ETH to fund the Put call
        vm.deal(caller, msgValue + 1 ether);

        // The Attacker will, when receiving ETH or otherwise, try reentering. We need to mark that
        // when c calls LogFile.AddMessage (LogFile is address(this)), this contract's AddMessage will be invoked.
        // Then inside AddMessage we will instruct the attacker to perform a reentrant call into c.Put.

